                "voice": "make_call",
                "messaging": "send_message",
                "video": "video_call"
            }
            required_apis = [type_mapping[t] for t in communication_types if t in type_mapping]
            if not all(api in supported_apis for api in required_apis):
                return json.dumps({
                    "success": False,
                    "message": f"Device {device.get('name')} does not support all requested communication types"
                })

        return json.dumps({
            "success": True,
            "message": f"Found communication device: {device.get('name')}",
            "device": device
        })

    # Get all devices with ANY communication capabilities
    all_devices = get_user_devices(data, user_id)
    communication_apis = ["make_call", "send_message", "video_call"]

    comm_devices = [
        device for device in all_devices
        if any(api in device.get("supported_apis", []) for api in communication_apis)
    ]

    # Filter by communication types if specified
    if communication_types:
        type_mapping = {
            "voice": "make_call",
            "messaging": "send_message",
            "video": "video_call"
        }
        required_apis = [type_mapping[t] for t in communication_types if t in type_mapping]

        comm_devices = [
            device for device in comm_devices
            if all(api in device.get("supported_apis", []) for api in required_apis)
        ]

    # Filter by name if provided
    if device_name:
        device_name_lower = device_name.lower()
        comm_devices = [
            device for device in comm_devices
            if device_name_lower in device.get("name", "").lower()
        ]

    # Return the devices
    if not comm_devices:
        message = "No communication devices found"
        if device_name:
            message += f" matching '{device_name}'"
        if communication_types:
            message += f" supporting {', '.join(communication_types)}"

        return json.dumps({
            "success": True,
            "message": message,
            "devices": []
        })

